const message = $('Telegram Trigger').item.json.message;
const userCaption = message.caption || "Insane Roblox funny moments, glitch, and gameplay";

const prompt = `You are an elite Roblox gaming YouTuber creating viral YouTube Shorts.
Topic/Context: "${userCaption}"

Create:
1. "title": A viral, high-CTR hook title strictly under 60 characters with gaming emojis ending with "#Shorts #Roblox" (e.g. "Bro Thought He Could Escape! 💀 #Shorts #Roblox" or "Only 1% of Roblox Players Know This! 🤯 #Shorts #Roblox").
2. "description": An exciting, suspenseful 2-sentence caption followed by viral hashtags: #Roblox #RobloxShorts #RobloxMemes #Shorts #Gaming #Viral.
3. "tags": 6-10 comma-separated keywords (e.g. "roblox, roblox shorts, roblox memes, roblox funny, blox fruits, roblox gameplay, gaming, viral").

Respond strictly in valid JSON only with NO markdown and NO extra text:
{
  "title": "Your Title Here #Shorts #Roblox",
  "description": "Your description here...\\n\\n#Roblox #RobloxShorts #RobloxMemes #Shorts #Gaming #Viral",
  "tags": "roblox, roblox shorts, roblox memes, roblox funny, blox fruits, gaming"
}`;

return {
  prompt: prompt,
  userCaption: userCaption,
  chatId: message.chat.id,
  messageId: message.message_id
};

let raw = $json.response;
let meta = {
  title: "Epic Roblox Moments! 🎮 #Shorts #Roblox",
  description: "Wait till the end! 💀 Like and subscribe for more Roblox shorts! #Roblox #RobloxShorts #RobloxMemes #Shorts #Gaming #Viral",
  tags: "roblox, roblox shorts, roblox memes, gaming"
};

try {
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (parsed.title) meta.title = parsed.title;
  if (parsed.description) meta.description = parsed.description;
  if (parsed.tags) {
    meta.tags = Array.isArray(parsed.tags) ? parsed.tags.join(',') : String(parsed.tags);
  }
} catch(e) {
  meta.description = raw;
}

if (!meta.title.toLowerCase().includes('#shorts')) {
  meta.title = `${meta.title.slice(0, 48)} #Shorts`;
}
if (!meta.title.toLowerCase().includes('#roblox')) {
  meta.title = `${meta.title} #Roblox`;
}

if (Array.isArray(meta.tags)) {
  meta.tags = meta.tags.join(',');
}

const binary = $('Download Telegram Video').item.binary;

return {
  json: {
    title: meta.title,
    description: meta.description,
    tags: String(meta.tags),
    chatId: $('Prepare Ollama Prompt').item.json.chatId
  },
  binary: binary
};

